  questions: [
    { id:'d22q1', q:'Qual nervo inerva o diafragma?', options:['Vago (X)','Frênico (C3–C5)','Intercostais','Torácico longo'], answer:1, explanation:'O nervo frênico (C3–C5) é motor do diafragma. "C3, 4, 5 keeps the diaphragm alive."', whyWrong:'Vago é visceral; intercostais inervam a parede; torácico longo inerva o serrátil.', difficulty:'iniciante', topic:'Diafragma' },
    { id:'d22q2', q:'Qual músculo é o principal responsável pela protração da escápula?', options:['Trapézio','Serrátil anterior','Grande dorsal','Romboides'], answer:1, explanation:'O serrátil anterior protrai (puxa para frente) a escápula e a mantém contra o tórax.', whyWrong:'Trapézio retrai; grande dorsal age no braço; romboides retraem.', difficulty:'intermediario', topic:'Serrátil anterior' },
    { id:'d22q3', q:'A lesão do nervo torácico longo manifesta-se como:', options:['Escápula alada medial','Escápula alada lateral','Queda do ombro','Incapacidade de fletir o braço'], answer:0, explanation:'Sem o serrátil anterior, a borda medial da escápula afasta-se do tórax — "asa medial".', whyWrong:'Asa lateral remete a trapézio (XI); queda do ombro, também XI.', difficulty:'intermediario', topic:'Serrátil — clínica' },
    { id:'d22q4', q:'Os músculos intercostais externos atuam na:', options:['Expiração forçada','Inspiração','Flexão do tronco','Protração'], answer:1, explanation:'Os intercostais externos elevam as costelas durante a inspiração.', whyWrong:'Expiração é interna/íntima + abdominais; flexão do tronco é abdominal.', difficulty:'intermediario', topic:'Intercostais' },
    { id:'d22q5', q:'O peitoral menor se insere em:', options:['Crista do tubérculo maior do úmero','Campo coracoide da escápula','Espinha da escápula','Clavícula lateral'], answer:1, explanation:'O peitoral menor vai das costelas ao processo coracoide — ele o puxa, protraindo a escápula.', whyWrong:'Peitoral maior insere no úmero; espinha é trapézio/deltoide; clavícula não.', difficulty:'avancado', topic:'Peitorais' },
    { id:'d22q6', q:'O nervo frênico origina-se de:', options:['C1–C2','C3–C5','C6–C8','T1–T4'], answer:1, explanation:'O frênico nasce das raízes C3, C4 e C5 do plexo cervical.', whyWrong:'C1–C2 formam o plexo hipoglosso; C6–C8 contribuem ao braquial; T1–T4 aos intercostais.', difficulty:'avancado', topic:'Diafragma' },
  ],
